create or replace function public.public_partner_profile_details(p_organization_id uuid)
returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('business_name',o.public_name,'description',p.public_description,'about',p.public_about,'website_url',o.website_url,'public_email',o.public_email,'public_phone',o.public_phone,'booking_url',p.public_booking_url,'order_url',p.public_order_url,'service_area',p.public_service_area,'business_model',p.business_model,'participation_state',p.participation_state,'social_links',coalesce((select jsonb_agg(jsonb_build_object('platform',s.platform,'url',s.url,'label',s.label)) from public.organization_social_links s where s.organization_id=o.id),'[]'::jsonb),'locations',coalesce((select jsonb_agg(jsonb_build_object('city',l.city,'state',l.state_province,'postal',l.postal_code)) from public.organization_locations l where l.organization_id=o.id),'[]'::jsonb),'hours',coalesce((select jsonb_agg(jsonb_build_object('day',h.day_of_week,'opens',h.opens_at,'closes',h.closes_at,'closed',h.is_closed)) from public.organization_business_hours h where h.organization_id=o.id),'[]'::jsonb)) from public.organization_partner_profiles p join public.organizations o on o.id=p.organization_id where p.organization_id=p_organization_id and p.publication_status='published'
$$;
revoke all on function public.public_partner_profile_details(uuid) from public,anon; grant execute on function public.public_partner_profile_details(uuid) to anon,authenticated;
